      <KV items={[['Methods', p.methods.join(', ')], ['Currencies', p.currencies.join(', ')], ['Markets', p.markets.join(', ')], ['Credentials', p.keyLabel ? p.keyLabel + ' (masked placeholder)' : <span className="bad-t">Not configured</span>], ['Callback', p.callback], ['Last simulated check', p.lastCheck ? `${fmtDT(p.lastCheck)} · ${p.health}` : 'Never'], ['Recent failures', p.failures]]} />
      {p.crypto && <><h3 className="sub-h">Crypto configuration</h3><KV items={[['Asset and network', p.crypto.pairs.map(([a, n]) => `${a} on ${n}`).join('; ')], ['Amount precision', p.crypto.precision + ' decimals'], ['Quote expiry', p.crypto.quoteMinutes + ' minutes'], ['Confirmations', p.crypto.confirmations], ['Underpayment', p.crypto.underpayment], ['Late payment', p.crypto.late], ['Unsupported networks', 'Recovery is not guaranteed']]} /></>}
