// ---------- security, health and business reports
export function SASecurity() {
  const { db, staff, act, perform } = useApp(); const g = useGate(['ssec']); if (g) return g;
  return <><PageTitle title="Security and audit" sub="Audit history cannot be edited or deleted. Secrets, codes, full payout credentials and identity document contents are never logged." actions={<ExportButton sensitive name="Audit log" rows={db.audit} cols={[['Time', a => new Date(a.at).toISOString()], ['Actor', a => a.actor], ['Role', a => a.role], ['Action', a => a.action], ['Object', a => a.object], ['Reason', a => a.reason], ['Outcome', a => a.outcome], ['Approval', a => a.approval || '']]} />} />
    <Section title="Security events (simulated)"><Table rows={db.securityEvents} cols={[{ k: 'at', label: 'Time', render: e => fmtDT(e.at) }, { k: 't', label: 'Type', render: e => e.type }, { k: 'w', label: 'Who', render: e => e.who }, { k: 'd', label: 'Detail', render: e => <span className="small">{e.detail}</span> }, { k: 's', label: 'Status', render: e => <Badge tone={e.status === 'Resolved' ? 'ok' : e.status === 'Investigating' ? 'warn' : 'muted'}>{e.status}</Badge> },
      { k: 'x', label: '', render: e => e.status === 'Investigating' && can(db, staff, 'audit.view') && <Btn size="sm" onClick={() => perform('resolveSecurityEvent', { eventId: e.id }, d => O.resolveSecurityEvent(d, staff, e.id), 'Marked resolved')}>Mark resolved</Btn> }]} /></Section>
    <Section title="Sensitive access and exports"><Table rows={db.audit.filter(a => a.sensitive || /Export|Role|Staff|Sessions|Integration|Environment/.test(a.action)).slice(0, 15)} empty={<p className="muted small">None yet.</p>} cols={[{ k: 'at', label: 'Time', render: a => fmtDT(a.at) }, { k: 'ac', label: 'Actor', render: a => a.actor }, { k: 'a', label: 'Action', render: a => a.action }, { k: 'o', label: 'Object', render: a => a.object }, { k: 'r', label: 'Reason', render: a => <span className="small">{a.reason}</span> }]} /></Section>
    <h2 className="sec-h">Audit log</h2>
    <AList id="audit" rows={db.audit} search={a => `${a.actor} ${a.action} ${a.object} ${a.reason} ${a.approval || ''}`} pageSize={12}
      filters={[{ k: 'ac', label: 'Actor', options: [...new Set(db.audit.map(a => a.actor))].map(x => [x, x]), test: (a, v) => a.actor === v }, { k: 'r', label: 'Role', options: [...new Set(db.audit.map(a => a.role))].map(x => [x, x]), test: (a, v) => a.role === v }, { k: 'o', label: 'Outcome', options: [...new Set(db.audit.map(a => a.outcome))].map(x => [x, x]), test: (a, v) => a.outcome === v }, { k: 'd', label: 'Date', options: [['1', 'Last 24 h'], ['7', 'Last 7 days']], test: (a, v) => a.at >= now() - +v * DAY }]}
      sorts={[{ id: 'new', label: 'Newest', fn: (a, b) => b.at - a.at }]}
      cols={[{ k: 'at', label: `Time (${tzName})`, render: a => <span className="xs">{fmtDT(a.at)}</span> }, { k: 'ac', label: 'Actor', render: a => <span className="small">{a.actor}<span className="xs muted block">{a.role}</span></span> }, { k: 'a', label: 'Action', render: a => <b className="small">{a.action}</b> }, { k: 'o', label: 'Object', render: a => <code className="xs">{a.object}</code> }, { k: 'r', label: 'Reason', render: a => <span className="small">{a.reason}</span> }, { k: 'c', label: 'Before → after', render: a => <span className="xs">{a.before || a.after ? `${a.before || '—'} → ${a.after || '—'}` : ''}</span> }, { k: 'ap', label: 'Request ref', render: a => a.approval || '' }, { k: 's', label: 'Outcome', render: a => <Badge tone={a.outcome === 'Success' ? 'ok' : 'warn'}>{a.outcome}</Badge> }]} /></>;
}
export function SAHealth() {
  const { db, staff, act, perform } = useApp(); const g = useGate(['sh']); const [rc, setRc] = useState(false); if (g) return g;
  const failedN = db.notifications.filter(n => n.delivery === 'Failed').length;
  const svc = [['Payment integrations', db.integrations.filter(i => i.enabled).every(i => i.health === 'Operational') ? 'Operational' : 'Degraded', db.integrations.map(i => `${i.name}: ${i.health}`).join('; ')], ['Payout integrations', db.payouts.some(p => p.status === 'Reconciliation required') ? 'Degraded' : 'Operational', `${db.payouts.filter(p => p.status === 'Reconciliation required').length} transfers awaiting reconciliation`], ['Notification delivery', failedN ? 'Degraded' : 'Operational', `${failedN} failed customer email deliveries`], ['Background tasks', db.tasks.some(t => t.status === 'Failed') ? 'Degraded' : 'Operational', `${db.tasks.filter(t => t.status === 'Failed').length} failed tasks`], ['File storage', 'Operational', 'Placeholder files only'], ['Backups', 'Operational', 'Last simulated backup 03:00 UTC; restoration check passed (simulated)']];
  return <><PageTitle title="System health" sub="Every status here is a demo indicator, not measured service performance. No uptime figures are shown." />
    <div className="health">{svc.map(([n, s, d]) => <div key={n} className={'hcard ' + (s === 'Operational' ? 'ok' : 'warn')}><div className="row-between"><b className="small">{n}</b><Badge tone={s === 'Operational' ? 'ok' : 'warn'}>{s}</Badge></div><span className="xs">{d}</span><span className="xs muted">Last checked {fmtDT(now() - 5 * 60e3)} · <Sim>Demo</Sim></span></div>)}</div>
    <Section title="Failed tasks"><Table rows={db.tasks} empty={<p className="muted small">No failed tasks.</p>} cols={[{ k: 't', label: 'Task', render: t => <b className="small">{t.type}</b> }, { k: 'r', label: 'Related record', render: t => <span className="small">{t.refLabel}</span> }, { k: 'a', label: 'Attempts', cls: 'num', render: t => t.attempts }, { k: 'e', label: 'Last error', render: t => <span className="xs">{t.lastError}</span> }, { k: 's', label: 'Status', render: t => <Badge tone={t.status === 'Failed' ? 'bad' : 'ok'}>{t.status}</Badge> },
      { k: 'x', label: 'Next permitted action', render: t => t.status === 'Failed' ? (can(db, staff, 'health.retry') ? <Btn size="sm" onClick={() => perform('retryTask', { taskId: t.id }, d => O.retryTask(d, staff, t.id), 'Retry run')}>Retry safely</Btn> : <span className="xs muted">Needs retry permission</span>) : '—' }]} />
      <p className="xs muted">Retrying a payment status query or notification never creates a financial entry. Uncertain money transfers are reconciled from their own record before any new attempt.</p></Section>
    <Section title="Backup and recovery"><KV items={[['Last backup', 'Today 03:00 UTC (simulated)'], ['Restoration check', 'Passed on a copy (simulated)'], ['Production restore', 'Not available in this prototype']]} /><Btn size="sm" onClick={() => setRc(true)}>View recovery checklist</Btn></Section>
    {rc && <Modal title="Recovery checklist (informational)" onClose={() => setRc(false)}><ol className="small"><li>Declare an incident and freeze money movement.</li><li>Identify the last consistent backup and the event log after it.</li><li>Restore into an isolated environment and reconcile provider events.</li><li>Verify balances against provider statements before reopening.</li><li>Record every step in the audit history.</li></ol><Notice tone="info">Demonstration only. No restore or destructive control exists here.</Notice></Modal>}
  </>;
}
export function SABizReports() {
  const { db, staff } = useApp(); const g = useGate(['sbr']); const [range, setRange] = useState(365); const [grp, setGrp] = useState('seller'); if (g) return g;
  const since = now() - range * DAY; const t = platformTotals(db, e => e.at >= since);
  const groups = grp === 'seller' ? Object.values(db.stores).map(s => ({ id: s.id, label: s.name, f: e => e.store === s.id })) : CATEGORIES.map(c => ({ id: c.id, label: c.name, f: e => db.orders.find(o => o.id === e.order)?.snap.cat === c.id }));
  const rows = groups.map(gp => { const x = platformTotals(db, e => e.at >= since && gp.f(e)); const b = grp === 'seller' ? storeBuckets(db, gp.id) : null; return { id: gp.id, label: gp.label, ...x, b }; }).filter(r => r.gross || r.b?.total);
  const ledgerSeller = db.ledger.filter(e => e.from === 'ext').reduce((a, e) => a + e.amt, 0); const f = sellerFundsAll(db); const all = platformTotals(db);
  const unmatched = db.recon.filter(r => r.status === 'Open');
  return <><PageTitle title="Business reports" sub={`USD. Grouped by transaction event date, last ${range} days, ${tzName}. Order-date reports would be labelled separately.`} actions={<><Seg label="Period" value={range} onChange={setRange} options={[{ id: 30, label: '30 d' }, { id: 365, label: '12 m' }]} /><Seg label="Group" value={grp} onChange={setGrp} options={[{ id: 'seller', label: 'By seller' }, { id: 'category', label: 'By category' }]} /><ExportButton name="Business report" rows={rows} cols={[['Group', r => r.label], ['Gross sales', r => (r.gross / 100).toFixed(2)], ['Refunded', r => (r.refunded / 100).toFixed(2)], ['Net sales', r => (r.net / 100).toFixed(2)], ['Net commission', r => (r.netRevenue / 100).toFixed(2)], ['Seller earnings', r => (r.sellerEarnings / 100).toFixed(2)]]} /></>} />
    <div className="report-grid">{[['Gross sales', t.gross], ['Refunded sales', t.refunded], ['Net sales', t.net], ['Gross commission', t.comm], ['Reversed commission', t.commRev], ['Net platform revenue', t.netRevenue], ['Seller earnings', t.sellerEarnings], ['Held funds (now)', f.held], ['Available funds (now)', f.available], ['Paid payouts (all time)', f.paidOut]].map(([k, c]) => <div key={k} className="report"><span className="xs muted">{k}</span><b>{fmtMoney(c)}</b></div>)}</div>
    <Section title={grp === 'seller' ? 'By seller' : 'By category'}><Table rows={rows} empty={<Empty title="No transactions in this period" />} cols={[{ k: 'l', label: grp === 'seller' ? 'Seller' : 'Category', render: r => <b className="small">{r.label}</b> }, { k: 'g', label: 'Gross', cls: 'num', render: r => <M c={r.gross} /> }, { k: 'r', label: 'Refunded', cls: 'num', render: r => <M c={r.refunded} /> }, { k: 'n', label: 'Net sales', cls: 'num', render: r => <M c={r.net} /> }, { k: 'c', label: 'Net commission', cls: 'num', render: r => <M c={r.netRevenue} /> }, { k: 's', label: 'Seller earnings', cls: 'num', render: r => <M c={r.sellerEarnings} /> }, ...(grp === 'seller' ? [{ k: 'h', label: 'Held', cls: 'num', render: r => <M c={r.b.held} /> }, { k: 'a', label: 'Available', cls: 'num', render: r => <M c={r.b.available} /> }, { k: 'res', label: 'Reserved', cls: 'num', render: r => <M c={r.b.reserved} /> }] : [])]} /></Section>
    <Section title="Reconciliation view (all time)"><KV items={[['Seller earnings credited (ledger)', fmtMoney(ledgerSeller)], ['Gross sales − gross commission (platform)', fmtMoney(all.gross - all.comm)], ['Match', ledgerSeller === all.gross - all.comm ? 'Yes' : 'No: investigate'], ['Seller funds across buckets', `${fmtMoney(f.total)} = pending ${fmtMoney(f.pending)} + held ${fmtMoney(f.held)} + available ${fmtMoney(f.available)} + reserved ${fmtMoney(f.reserved)}`], ['Credited − refund reversals − paid out', fmtMoney(ledgerSeller - f.refunded - f.paidOut) + (ledgerSeller - f.refunded - f.paidOut === f.total ? ' (matches)' : ' (mismatch)')], ['Unmatched provider events', unmatched.length ? unmatched.map(r => `${r.id} ${r.type} ${fmtMoney(r.amountC)}`).join('; ') : 'None']]} /></Section></>;
}
export function SAPolicies() {
  const { db, staff, act, perform } = useApp(); const g = useGate(['spol']); const [dlg, setDlg] = useState(null); const [pv, setPv] = useState(null); if (g) return g;
  return <><PageTitle title="Policies" sub="Draft, review, publish. Orders keep the version accepted at checkout. Placeholder text only; no legal terms are claimed as approved." />
    {db.policies.map(p => <Section key={p.id} title={p.title}><Table rows={p.versions.slice().reverse().map(v => ({ ...v, id: v.v }))} cols={[{ k: 'v', label: 'Version', render: v => 'v' + v.v }, { k: 's', label: 'State', render: v => <Badge tone={{ Published: 'ok', 'In review': 'info', Draft: 'muted' }[v.state] || 'muted'}>{v.state}</Badge> }, { k: 'a', label: 'Author', render: v => v.author }, { k: 'r', label: 'Reviewer', render: v => v.reviewer || v.publishedBy || '—' }, { k: 'e', label: 'Published', render: v => v.publishedAt ? fmtDate(v.publishedAt) : '—' }, { k: 'c', label: 'Orders accepting', cls: 'num', render: v => db.orders.filter(o => o.termsVersion === `Terms v${v.v}`).length }, { k: 'x', label: '', render: v => <div className="row-acts"><Btn size="sm" v="ghost" onClick={() => setPv({ p, v })}>Preview</Btn>{v.state === 'In review' && <Btn size="sm" disabled={!can(db, staff, 'policies.publish')} onClick={() => setDlg(p)}>Publish</Btn>}</div> }]} /></Section>)}
    {pv && <Modal title={`${pv.p.title} v${pv.v.v} (preview)`} onClose={() => setPv(null)}><Notice tone="warn">Placeholder content.</Notice><p>{pv.v.content}</p></Modal>}
    {dlg && <ReasonDialog title={`Publish ${dlg.title}`} intro="Updates the website and creates an audit event. Existing orders keep their accepted version." confirm="Publish" onClose={() => setDlg(null)} onSubmit={v => perform('publishPolicy', { policyId: dlg.id, reason: v.reason }, d => O.publishPolicyDraft(d, staff, dlg.id, v.reason), 'Policy published')} />}
  </>;
}
